767 :         // compute coefficients of the cubic equation as: x^3 + b x^2 + c x + d = 0
768 :         final double b        = -(q0 + q1 + q2);
769 :         final double c        = q0 * q1 + q0 * q2 + q1q2Me22 - e12;
770 :         final double d        = q2 * e12 - q0 * q1q2Me22;
771 : 
772 :         // solve cubic equation
773 :         final double b2       = b * b;
774 :         final double q        = (3 * c - b2) / 9;
775 :         final double r        = ((9 * c - 2 * b2) * b - 27 * d) / 54;
776 :         final double delta    = q * q * q + r * r;
